"use client";

import * as React from "react";
import { cn } from "@/lib/utils";

export type CursorFlareItem = {
  id: string;
  label: string;
  value: string;
  hint?: string;
};

export type CursorFlareProps = {
  items: CursorFlareItem[];
  className?: string;
  headline?: string;
};

/**
 * Shared cursor spotlight across a KPI grid — the flare follows the pointer
 * and brightens the tile under it while soft-dimming siblings.
 */
function CursorFlare({
  items,
  className,
  headline = "Live surface",
}: CursorFlareProps) {
  const rootRef = React.useRef<HTMLDivElement>(null);
  const [pos, setPos] = React.useState({ x: 50, y: 40 });
  const [activeId, setActiveId] = React.useState<string | null>(
    items[0]?.id ?? null,
  );

  const onMove = (e: React.MouseEvent<HTMLDivElement>) => {
    const el = rootRef.current;
    if (!el) return;
    const r = el.getBoundingClientRect();
    setPos({
      x: ((e.clientX - r.left) / r.width) * 100,
      y: ((e.clientY - r.top) / r.height) * 100,
    });
  };

  return (
    <div
      ref={rootRef}
      onMouseMove={onMove}
      onMouseLeave={() => setActiveId(items[0]?.id ?? null)}
      className={cn(
        "relative overflow-hidden rounded-2xl border border-border bg-card p-4 shadow-[var(--shadow-soft)] sm:p-5",
        className,
      )}
    >
      <div
        aria-hidden
        className="pointer-events-none absolute inset-0 transition-[background] duration-150"
        style={{
          background: `radial-gradient(420px circle at ${pos.x}% ${pos.y}%, color-mix(in oklch, var(--color-primary) 18%, transparent), transparent 55%)`,
        }}
      />
      <div className="relative mb-3 text-xs font-medium text-muted-foreground">
        {headline}
      </div>
      <div className="relative grid grid-cols-2 gap-2 sm:grid-cols-4">
        {items.map((item) => {
          const active = activeId === item.id;
          return (
            <button
              key={item.id}
              type="button"
              onMouseEnter={() => setActiveId(item.id)}
              className={cn(
                "rounded-xl border border-border/70 bg-background/70 p-3 text-left transition-[opacity,transform,box-shadow] duration-200",
                active
                  ? "opacity-100 shadow-[var(--shadow-lift)] scale-[1.02]"
                  : "opacity-55 hover:opacity-80",
              )}
            >
              <div className="text-[11px] text-muted-foreground">{item.label}</div>
              <div className="mt-1 text-lg font-semibold tabular-nums tracking-tight">
                {item.value}
              </div>
              {item.hint ? (
                <div className="mt-1 text-[11px] text-muted-foreground">
                  {item.hint}
                </div>
              ) : null}
            </button>
          );
        })}
      </div>
    </div>
  );
}

export { CursorFlare };
